import anthropic
client = anthropic.Anthropic()

message = client.messages.create(
    model="claude-opus-4-5",
    max_tokens=512,
    system="You are a JSON-only API. Respond with valid JSON and nothing else.",
    messages=[{
        "role": "user",
        "content": "Extract the name, email, and company from: John Smith, john@acme.com, Acme Corp"
    }]
)
print(message.content[0].text)
# {"name":"John Smith","email":"john@acme.com","company":"Acme Corp"}
